class Kanea < Formula
  desc "Container orchestration in one binary"
  homepage "https://github.com/m18h/kanea"
  version "0.13.0"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_linux do
    on_arm do
      url "https://github.com/m18h/kanea/releases/download/v0.13.0/kanea_0.13.0_linux_arm64.tar.gz"
      sha256 "3abf559a00335c0e40b9848cd0808bf586ebd45523606d8723de27fb149fbd0c"
    end
    on_intel do
      url "https://github.com/m18h/kanea/releases/download/v0.13.0/kanea_0.13.0_linux_amd64.tar.gz"
      sha256 "c0905895c3e1f618935d3ae6aa0c3c2fd1a99ca5dda9dcdd5a911d3d4dca2a64"
    end
  end

  def install
    bin.install "kanea"
  end

  def caveats
    <<~EOS
      The platform (kanead, kanea-edge, kanea init) runs on Linux. On macOS
      this is the authoring CLI: kanea plan validates job specs with file and
      line diagnostics before anything touches a node.

      To set up a Linux node: https://github.com/m18h/kanea#install
    EOS
  end

  test do
    assert_match "kanea v#{version}", shell_output("#{bin}/kanea version")

    # A spec that fails validation proves the real parser is in the binary:
    # plan diagnoses before it dials, so no daemon is needed.
    (testpath/"bad.hcl").write <<~HCL
      service "web" {}
    HCL
    output = shell_output("#{bin}/kanea plan #{testpath}/bad.hcl 2>&1", 1)
    assert_match "problem", output
  end
end
